VIK = [{'id': 1, 'nombre': 'La huida', 'mapa': 'estepa', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 5, 'rival': 3}, 'objetivo': {'tipo': 'escapar', 'equipo': 0, 'lado': 'oeste'}, 'dificultad': 'facil', 'limite': 15, 'guion': [{'id': 'jinetes_knut', 'repetible': True, 'cuando': {'cadaTurnos': 4, 'desde': 4}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero'], 'donde': 'borde'}, 'aviso': 'jinetes'}}], 'enemigos': [{'bando': 'noruega', 'reino': 'Los hombres de Knut'}], 'voz': 'Rognvald, tu amigo', 'historia': 'Tu hermano, el rey Olaf, ha muerto en la batalla. Tú solo tienes quince años y estás herido. Knut, el rey que ha ganado, manda a sus hombres a buscarte por los bosques. Al otro lado de estas tierras hay un barco esperándonos. Si llegamos, podremos huir lejos.', 'meta': 'Lleva a tu héroe a una de las casillas con bandera 🚩, abajo a la izquierda: allí está el barco. Tienes {t} turnos. Si se acaban y no ha salido, pierdes. Y si matan a tu héroe, también.', 'contra': 'Los hombres de Knut', 'consejo': 'No hace falta ganar a nadie. Que tus soldados se pongan delante de tu héroe y le abran el camino.', 'avisos': {'jinetes': '¡Más jinetes de Knut vienen a buscarte!'}, 'en': {'nombre': 'The escape', 'voz': 'Rognvald, your friend', 'historia': 'Your brother, King Olaf, has died in battle. You are only fifteen and you are hurt. Knut, the king who won, has sent his men to look for you in the woods. On the other side of this land a ship is waiting for us. If we get there, we can run far away.', 'meta': "Take your hero to one of the hexes with a flag 🚩, at the bottom left: the ship is there. You have {t} turns. If they run out and your hero hasn't got out, you lose. And if your hero is killed, you lose too.", 'contra': "Knut's men", 'consejo': "You don't need to beat anyone. Put your soldiers in front of your hero and let them clear the way.", 'avisos': {'jinetes': "More of Knut's riders are coming to find you!"}}}, {'id': 2, 'nombre': 'La guardia del emperador', 'mapa': 'costa', 'rivales': 1, 'batalla': 'clave', 'objetivo': {'tipo': 'clave', 'n': 2, 'turnos': 2}, 'dificultad': 'normal', 'limite': 12, 'enemigos': [{'bando': 'venecia', 'reino': 'Los piratas del estrecho'}], 'voz': 'El capitán de la guardia', 'historia': 'Has cruzado el mar hasta Constantinopla, la ciudad más grande del mundo. Su emperador paga en oro a los guerreros del norte que le protegen: su guardia. Pero aquí nadie te conoce. Unos piratas se han quedado con las torres del puerto. Si se las quitas, entrarás en la guardia.', 'meta': 'En el mapa hay torres marcadas con una estrella. Pisa dos de ellas con tus soldados y consigue que sigan siendo tuyas durante dos turnos seguidos. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los piratas del estrecho', 'consejo': 'Los piratas intentarán recuperar las torres. Deja un soldado encima de cada una.', 'en': {'nombre': "The emperor's guard", 'voz': 'The captain of the guard', 'historia': "You have crossed the sea to Constantinople, the biggest city in the world. Its emperor pays gold to the northern warriors who protect him: his guard. But nobody knows you here. Some pirates have taken the towers of the harbour. If you take them back, you'll join the guard.", 'meta': 'There are towers on the map marked with a star. Step on two of them with your soldiers and keep them yours for two turns in a row. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The pirates of the strait', 'consejo': 'The pirates will try to take the towers back. Leave a soldier on top of each one.'}}, {'id': 3, 'nombre': 'La isla de los castillos', 'mapa': 'isla', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 12, 'dificultad': 'normal', 'limite': 28, 'guion': [{'id': 'barcos_emperador', 'cuando': {'turno': 3}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['catapulta', 'catapulta'], 'donde': 'borde'}, 'aviso': 'catapultas'}}], 'enemigos': [{'bando': 'abasi', 'reino': 'Los señores de la isla'}, {'bando': 'abasi', 'reino': 'Los señores del puerto'}], 'voz': 'El capitán de la guardia', 'historia': 'Ya eres de la guardia del emperador. Ahora te manda a Sicilia, una isla del sur llena de castillos. Si tomas el castillo más grande, podrás quedarte con una parte del tesoro. Por primera vez vas a mandar a tus propios hombres.', 'meta': 'Aquí no tienes pueblo: solo tu ejército, que llega en barco. Conquista el castillo de los señores de la isla, que es su pueblo principal. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los señores de la isla y los del puerto. Cada uno va por su cuenta', 'consejo': 'Aquí no puedes reclutar soldados, así que cuídalos. Sin catapultas cuesta mucho romper una muralla.', 'avisos': {'catapultas': 'Llegan más barcos del emperador con dos catapultas. Sirven para romper murallas.'}, 'en': {'nombre': 'The island of castles', 'voz': 'The captain of the guard', 'historia': "You are in the emperor's guard now. He is sending you to Sicily, an island in the south full of castles. If you take the biggest castle, you can keep part of the treasure. For the first time you will lead your own men.", 'meta': "You have no village here: only your army, which arrives by ship. Conquer the castle of the lords of the island, which is their main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The lords of the island and the lords of the harbour. Each fights for himself', 'consejo': "You can't recruit soldiers here, so look after them. Without catapults it's very hard to break a wall.", 'avisos': {'catapultas': "More of the emperor's ships arrive with two catapults. They are for breaking walls."}}}, {'id': 4, 'nombre': 'El tesoro escondido', 'mapa': 'sierra', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'aguantar', 'equipo': 0, 'turnos': 14, 'capital': True}, 'dificultad': 'normal', 'limite': 14, 'guion': [{'id': 'soldados_emperador', 'repetible': True, 'cuando': {'cadaTurnos': 2, 'desde': 3}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['lancero', 'espadachin', 'catapulta', 'caballero'], 'donde': 'borde'}, 'aviso': 'soldados'}}], 'enemigos': [{'bando': 'bizancio', 'reino': 'Los soldados del emperador'}, {'bando': 'bizancio', 'reino': 'La guardia del palacio'}], 'voz': 'Rognvald, tu amigo', 'historia': 'Has ganado mucho oro en Sicilia, y ahora el emperador lo quiere para él. Dice que es suyo. Hemos escondido el tesoro en las montañas y hemos mandado a buscar un barco. Hasta que llegue, tenemos que aguantar aquí.', 'meta': 'Defiende tu pueblo principal (el de la estrella) durante {t} turnos, hasta que llegue el barco. Si te lo quitan, pierdes. Si al acabar el turno {t} sigue siendo tuyo, ganas.', 'contra': 'Los soldados del emperador y la guardia del palacio, que van juntos', 'consejo': 'Llena tu pueblo principal de soldados y ponle murallas. Los demás pueblos no importan tanto.', 'avisos': {'soldados': '¡El emperador manda más soldados a buscar su oro, con una catapulta para romper tus murallas!'}, 'en': {'nombre': 'The hidden treasure', 'voz': 'Rognvald, your friend', 'historia': "You won a lot of gold in Sicily, and now the emperor wants it for himself. He says it's his. We have hidden the treasure in the mountains and sent for a ship. Until it arrives, we have to hold out here.", 'meta': "Defend your main village (the one with the star) for {t} turns, until the ship arrives. If they take it, you lose. If it's still yours at the end of turn {t}, you win.", 'contra': "The emperor's soldiers and the palace guard, who fight together", 'consejo': "Fill your main village with soldiers and give it walls. Your other villages don't matter as much.", 'avisos': {'soldados': 'The emperor is sending more soldiers after his gold, with a catapult to break your walls!'}}}, {'id': 5, 'nombre': 'El príncipe del este', 'mapa': 'hoz', 'rivales': 2, 'dificultad': 'normal', 'limite': 18, 'guion': [{'id': 'ayuda_elisiv', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'caballero', 'lancero'], 'donde': 'capital'}, 'aviso': 'ayuda'}}, {'id': 'ayuda_elisiv2', 'cuando': {'turno': 8}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['espadachin', 'arquero', 'caballero'], 'donde': 'capital'}, 'aviso': 'ayuda2'}}], 'enemigos': [{'bando': 'polonia', 'reino': 'Los bandidos del río'}, {'bando': 'polonia', 'reino': 'Los bandidos del bosque'}], 'voz': 'Elisiv, la hija del príncipe', 'historia': 'Con el oro a salvo has llegado a Kiev, la tierra del gran príncipe del este. Yo soy su hija, Elisiv. Mi padre dice que me casaré contigo si echas a los bandidos que roban en los caminos. Yo ya he dicho que sí.', 'meta': 'Acaba con los dos grupos de bandidos: quítales sus pueblos y derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los bandidos del río y los del bosque, que van juntos', 'consejo': 'Van juntos: no dejes tus pueblos vacíos. Aguanta los primeros turnos: el príncipe puede ayudarte.', 'avisos': {'ayuda': 'Elisiv convence a su padre, y el príncipe te manda dos caballeros y un lancero.', 'ayuda2': 'El príncipe te manda más gente: un espadachín, un arquero y un caballero.'}, 'en': {'nombre': 'The prince of the east', 'voz': "Elisiv, the prince's daughter", 'historia': 'With the gold safe you have reached Kiev, the land of the great prince of the east. I am his daughter, Elisiv. My father says I will marry you if you drive out the bandits who rob people on the roads. I have already said yes.', 'meta': 'Beat both groups of bandits: take their villages and defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The river bandits and the forest bandits, who fight together', 'consejo': "They fight together: don't leave your villages empty. Hold on for the first turns: the prince may help you.", 'avisos': {'ayuda': 'Elisiv talks her father round, and the prince sends you two knights and a spearman.', 'ayuda2': 'The prince sends you more people: a swordsman, an archer and a knight.'}}, 'equipos': [0, 1, 1]}, {'id': 6, 'nombre': 'Vuelta a casa', 'mapa': 'torres', 'rivales': 2, 'equipos': [0, 1, 0], 'objetivo': {'tipo': 'tomar', 'jugador': 1}, 'dificultad': 'normal', 'limite': 34, 'guion': [{'id': 'barco', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['lancero', 'espadachin', 'catapulta', 'catapulta'], 'donde': '2,9'}, 'aviso': 'barco'}}, {'id': 'barco2', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'caballero', 'catapulta'], 'donde': '3,9'}, 'aviso': 'barco2'}}, {'id': 'magnus_traiciona', 'cuando': {'turno': 7}, 'hacer': {'equipo': {'jugador': 2, 'nuevo': 1}, 'aviso': 'traicion'}}], 'enemigos': [{'bando': 'noruega', 'reino': 'Los jefes del fiordo'}, {'bando': 'noruega', 'reino': 'Magnus, tu sobrino'}], 'voz': 'Elisiv, tu esposa', 'historia': 'Volvemos a Noruega con un barco lleno de oro. Ahora el rey es tu sobrino Magnus. Dice que compartirá la corona contigo y que te ayudará contra los jefes del fiordo, que no te quieren aquí. Ojalá sea verdad.', 'meta': 'Conquista el pueblo principal de los jefes del fiordo. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los jefes del fiordo. Magnus, tu sobrino, empieza de tu lado', 'consejo': 'No dejes tus pueblos vacíos. Una corona es difícil de compartir.', 'avisos': {'traicion': '¡Magnus no quiere compartir la corona! Se pasa al lado de los jefes del fiordo. Ahora es tu enemigo.', 'barco': 'Tus hombres de confianza llegan en barco, cerca del pueblo de los jefes: un lancero, un espadachín y dos catapultas para romper murallas.', 'barco2': 'Llega otro barco con dos caballeros y otra catapulta, también cerca del pueblo de los jefes.'}, 'en': {'nombre': 'Home again', 'voz': 'Elisiv, your wife', 'historia': "We are going back to Norway with a ship full of gold. The king now is your nephew Magnus. He says he will share the crown with you and help you against the chiefs of the fjord, who don't want you here. Let's hope it's true.", 'meta': "Conquer the main village of the chiefs of the fjord. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The chiefs of the fjord. Magnus, your nephew, starts on your side', 'consejo': "Don't leave your villages empty. A crown is hard to share.", 'avisos': {'traicion': "Magnus doesn't want to share the crown! He goes over to the chiefs of the fjord. Now he is your enemy.", 'barco': "Your most trusted men arrive by ship, near the chiefs' village: a spearman, a swordsman and two catapults for breaking walls.", 'barco2': 'Another ship arrives with two knights and another catapult, also near the chiefs’ village.'}}, 'hucha': None}, {'id': 7, 'nombre': 'El rey de Dinamarca', 'mapa': 'costa', 'rivales': 3, 'batalla': 'campo', 'ejercito': {'yo': 18, 'rival': 5}, 'equipos': [0, 1, 1, 1], 'dificultad': 'dificil', 'limite': 15, 'enemigos': [{'bando': 'noruega', 'reino': 'Los barcos de Svein'}, {'bando': 'noruega', 'reino': 'Los guerreros de Svein'}, {'bando': 'noruega', 'reino': 'Los jinetes de Svein'}], 'voz': 'Rognvald, tu amigo', 'historia': 'Magnus ha muerto y ahora eres el único rey de Noruega. Pero Svein, el rey de Dinamarca, quiere tus tierras, y sus barcos han llegado a nuestras islas. Ellos pelean como nosotros: esto va a ser duro.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Tres grupos de barcos de Svein, que van juntos', 'consejo': 'Tienes más soldados que cada uno de sus grupos. Júntalos y ataca a cada enemigo con varios a la vez.', 'en': {'nombre': 'The king of Denmark', 'voz': 'Rognvald, your friend', 'historia': 'Magnus is dead and now you are the only king of Norway. But Svein, the king of Denmark, wants your lands, and his ships have reached our islands. They fight like we do: this is going to be hard.', 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "Three groups of Svein's ships, who fight together", 'consejo': 'You have more soldiers than each of their groups. Keep yours together and attack each enemy with several at once.'}}, {'id': 8, 'nombre': 'Las islas del norte', 'mapa': 'isla', 'rivales': 3, 'dificultad': 'dificil', 'limite': 18, 'guion': [{'id': 'conde_orcadas', 'cuando': {'turno': 4}, 'hacer': {'equipo': {'jugador': 3, 'nuevo': 0}, 'aviso': 'conde'}}], 'enemigos': [{'bando': 'escocia', 'reino': 'Los señores de las islas'}, {'bando': 'escocia', 'reino': 'Los señores del cabo'}, {'bando': 'escocia', 'reino': 'El conde de las Orcadas'}], 'voz': 'Un mensajero inglés', 'historia': 'Traigo noticias de Inglaterra, señor: nuestro rey ha muerto sin hijos. Muchos dicen que la corona podría ser vuestra. Pero para cruzar el mar con un ejército necesitáis antes las islas del norte, y sus señores no quieren dueño.', 'meta': 'Acaba con los señores de las islas: quítales sus pueblos y derrota a sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los señores de las islas, los del cabo y el conde de las Orcadas, que de momento van juntos', 'consejo': 'No todos quieren pelear contigo para siempre. Aguanta sin perder tus pueblos.', 'avisos': {'conde': 'El conde de las Orcadas decide que prefiere ser tu amigo. Ahora está de tu lado.'}, 'en': {'nombre': 'The northern isles', 'voz': 'An English messenger', 'historia': 'I bring news from England, my lord: our king has died with no children. Many say the crown could be yours. But to cross the sea with an army you need the northern isles first, and their lords want no master.', 'meta': 'Beat the lords of the isles: take their villages and defeat their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The lords of the isles, the lords of the cape and the earl of Orkney, who fight together for now', 'consejo': 'Not everyone wants to fight you forever. Hold on without losing your villages.', 'avisos': {'conde': "The earl of Orkney decides he'd rather be your friend. Now he's on your side."}}, 'equipos': [0, 1, 1, 1]}, {'id': 9, 'nombre': 'Fulford', 'mapa': 'costa', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'heroe'}, 'dificultad': 'dificil', 'limite': 14, 'guion': [{'id': 'avanzadilla', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero', 'caballero', 'arquero'], 'donde': 'borde'}, 'aviso': 'avanzadilla'}}], 'enemigos': [{'faccion': 'inglaterra', 'reino': 'El conde Edwin'}, {'faccion': 'inglaterra', 'reino': 'El conde Morcar'}], 'voz': 'Rognvald, tu amigo', 'historia': 'Hemos llegado a Inglaterra con trescientos barcos. Dos condes, Edwin y Morcar, nos esperan con sus hombres junto a un río, cerca de la ciudad de York. Si los vencemos rápido, la ciudad nos abrirá sus puertas antes de que llegue el rey inglés con su ejército.', 'meta': 'Aquí no hay pueblos: solo los ejércitos. Mata a los héroes de los dos condes y que el tuyo siga vivo. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'El conde Edwin y el conde Morcar, que van juntos', 'consejo': 'Cuidado con tu héroe: si lo matan a él, pierdes. Ataca a sus héroes con varios soldados a la vez.', 'avisos': {'avanzadilla': '¡Llegan los primeros jinetes del rey inglés! El rey no puede estar lejos.'}, 'en': {'nombre': 'Fulford', 'voz': 'Rognvald, your friend', 'historia': 'We have reached England with three hundred ships. Two earls, Edwin and Morcar, are waiting for us with their men by a river, near the city of York. If we beat them quickly, the city will open its gates before the English king arrives with his army.', 'meta': 'There are no villages here: only the armies. Kill the heroes of both earls and keep yours alive. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'Earl Edwin and Earl Morcar, who fight together', 'consejo': 'Look after your hero: if yours is killed, you lose. Attack their heroes with several soldiers at once.', 'avisos': {'avanzadilla': "The English king's first riders are here! The king can't be far away."}}, 'batalla': 'campo', 'ejercito': {'yo': 16, 'rival': 6}}, {'id': 10, 'nombre': 'El puente de Stamford', 'mapa': 'torres', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': None, 'dificultad': 'dificil', 'limite': 32, 'guion': [{'id': 'eystein', 'cuando': {'turno': 6}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['espadachin', 'espadachin', 'arquero', 'caballero'], 'donde': 'borde'}, 'aviso': 'eystein'}}, {'id': 'maquinas_fiordo', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'catapulta', 'catapulta'], 'donde': 'borde'}, 'aviso': 'maquinas'}}], 'enemigos': [{'bando': 'inglaterra', 'capital': 'York'}, {'bando': 'inglaterra', 'reino': 'Los sajones'}], 'voz': 'Harold, rey de Inglaterra', 'historia': '«Harald de Noruega. Has venido a por mi reino. Te daré un trozo de Inglaterra: dos metros de tierra, lo que ocupa un hombre tumbado.» Harold, el rey inglés, te habla desde el otro lado del puente. «Mi ejército ha corrido día y noche para llegar. Te estamos esperando.»', 'meta': 'Aquí no tienes pueblo: solo tu ejército, que ha llegado en barco. Conquista el pueblo principal del rey Harold. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Harold, rey de Inglaterra, y los sajones, que van juntos', 'consejo': 'Es la última batalla. Harold es muy fuerte: no le ataques con un soldado solo.', 'avisos': {'eystein': 'Llega Eystein con los hombres que se quedaron guardando los barcos: dos espadachines, un arquero y un caballero.', 'maquinas': 'Llegan los últimos barcos: un caballero y dos catapultas para romper la muralla de Harold.'}, 'en': {'nombre': 'Stamford Bridge', 'voz': 'Harold, King of England', 'historia': '«Harald of Norway. You have come for my kingdom. I will give you a piece of England: two metres of earth, as much as a man lying down.» Harold, the English king, speaks to you from the other side of the bridge. «My army has run day and night to get here. We are waiting for you.»', 'meta': "You have no village here: only your army, which came by ship. Conquer King Harold's main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'Harold, King of England, and the Saxons, who fight together', 'consejo': "This is the last battle. Harold is very strong: don't attack him with just one soldier.", 'avisos': {'eystein': 'Eystein arrives with the men who stayed behind guarding the ships: two swordsmen, an archer and a knight.', 'maquinas': 'The last ships arrive: a knight and two catapults to break Harold’s wall.'}}, 'batalla': 'asalto', 'ejercito': 18}]
ING = [{'id': 1, 'nombre': 'El príncipe preso', 'mapa': 'costa', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 5, 'rival': 4}, 'dificultad': 'facil', 'limite': 12, 'enemigos': [{'bando': 'inglaterra', 'reino': 'Los guardias del conde'}], 'voz': 'Tu amigo Tomás', 'historia': 'Tu padre, el rey de Inglaterra, perdió una batalla contra el conde Simón. Desde entonces el conde os tiene presos a los dos y manda él en el reino. Hoy los guardias te dejan salir a montar a caballo. Tus amigos te esperan fuera. Es ahora o nunca.', 'meta': 'Aquí no hay pueblos: solo tus amigos contra los guardias. Derrota a todos los guardias del conde. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los guardias del conde Simón', 'consejo': 'Ataca a cada guardia con dos o tres soldados a la vez: así caen antes.', 'en': {'nombre': 'The captive prince', 'voz': 'Your friend Thomas', 'historia': "Your father, the King of England, lost a battle against Earl Simon. Since then the earl has kept you both prisoner and rules the kingdom himself. Today the guards let you out to go riding. Your friends are waiting outside. It's now or never.", 'meta': "There are no villages here: only your friends against the guards. Defeat all the earl's guards. You have {t} turns. If they run out first, whoever has more points wins.", 'contra': "Earl Simon's guards", 'consejo': 'Attack each guard with two or three soldiers at once: they fall faster.'}}, {'id': 2, 'nombre': 'La carrera de caballos', 'mapa': 'sierra', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 5, 'rival': 5}, 'objetivo': {'tipo': 'escapar', 'equipo': 0, 'lado': 'oeste'}, 'dificultad': 'normal', 'limite': 14, 'guion': [{'id': 'persecucion', 'repetible': True, 'cuando': {'cadaTurnos': 4, 'desde': 4}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero'], 'donde': 'borde'}, 'aviso': 'jinetes'}}], 'enemigos': [{'bando': 'inglaterra', 'reino': 'Los jinetes del conde'}], 'voz': 'Roger Mortimer, un señor amigo', 'historia': '¡Muy listo, príncipe! Hiciste carreras con los caballos de tus guardias hasta cansarlos, y te escapaste en el único que estaba fresco. Ahora te persiguen. Cruza las montañas hasta mis tierras y aquí estarás a salvo.', 'meta': 'Lleva a tu héroe a una de las casillas con bandera 🚩, abajo a la izquierda: allí empiezan las tierras de Mortimer. Tienes {t} turnos. Si se acaban y no ha salido, pierdes. Y si matan a tu héroe, también.', 'contra': 'Los jinetes del conde', 'consejo': 'No hace falta ganar a nadie. Que tus soldados frenen a los jinetes mientras tu héroe avanza.', 'avisos': {'jinetes': '¡Más jinetes del conde se unen a la persecución!'}, 'en': {'nombre': 'The horse race', 'voz': 'Roger Mortimer, a friendly lord', 'historia': "Very clever, prince! You raced your guards' horses until they were tired, and escaped on the only fresh one. Now they are chasing you. Cross the mountains to my lands and you'll be safe here.", 'meta': "Take your hero to one of the hexes with a flag 🚩, at the bottom left: Mortimer's lands begin there. You have {t} turns. If they run out and your hero hasn't got out, you lose. And if your hero is killed, you lose too.", 'contra': "The earl's riders", 'consejo': "You don't need to beat anyone. Let your soldiers hold back the riders while your hero moves on.", 'avisos': {'jinetes': "More of the earl's riders join the chase!"}}}, {'id': 3, 'nombre': 'Los señores de la frontera', 'mapa': 'torres', 'rivales': 2, 'dificultad': 'facil', 'limite': 18, 'guion': [{'id': 'frontera', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['lancero', 'arquero', 'caballero', 'caballero', 'espadachin'], 'donde': 'capital'}, 'aviso': 'frontera'}}, {'id': 'frontera2', 'cuando': {'turno': 8}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['espadachin', 'arquero', 'caballero'], 'donde': 'capital'}, 'aviso': 'frontera2'}}], 'enemigos': [{'bando': 'escocia', 'reino': 'Los barones del valle'}, {'bando': 'escocia', 'reino': 'Los barones del río'}], 'voz': 'Roger Mortimer', 'historia': 'Estás a salvo en mis tierras, pero un príncipe sin ejército no asusta a nadie. Los señores de la frontera todavía no se fían de ti. Echa a los barones del conde que hay en el valle, y verán de qué eres capaz.', 'meta': 'Acaba con los barones: quítales sus pueblos y derrota a sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los barones del valle y los del río, que van juntos', 'consejo': 'Aguanta los primeros turnos sin perder tus pueblos: si te ven fuerte, puede que alguien se anime a ayudarte.', 'avisos': {'frontera': 'Los señores de la frontera han visto cómo peleas y te mandan soldados: un lancero, un arquero, un espadachín y dos caballeros.', 'frontera2': 'Llegan más señores de la frontera: un espadachín, un arquero y un caballero.'}, 'en': {'nombre': 'The border lords', 'voz': 'Roger Mortimer', 'historia': "You are safe in my lands, but a prince with no army scares nobody. The border lords don't trust you yet. Drive out the earl's barons from the valley, and they'll see what you can do.", 'meta': 'Beat the barons: take their villages and defeat their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The barons of the valley and the barons of the river, who fight together', 'consejo': "Get through the first turns without losing your villages: if they see you're strong, someone may decide to help you.", 'avisos': {'frontera': 'The border lords have seen how you fight and send you soldiers: a spearman, an archer, a swordsman and two knights.', 'frontera2': 'More border lords arrive: a swordsman, an archer and a knight.'}}, 'equipos': [0, 1, 1]}, {'id': 4, 'nombre': 'Los puentes del Severn', 'mapa': 'hoz', 'rivales': 2, 'batalla': 'clave', 'objetivo': {'tipo': 'clave', 'n': 2, 'turnos': 3}, 'equipos': None, 'dificultad': 'normal', 'limite': 16, 'enemigos': [{'bando': 'escocia', 'reino': 'Los galeses del conde'}, {'bando': 'inglaterra', 'reino': 'Los barones rebeldes'}], 'voz': 'Roger Mortimer', 'historia': 'Ya tienes ejército. El conde Simón está al otro lado del Severn, un río muy grande, y los galeses le ayudan. Solo hay dos sitios para cruzar el río. Si los cerramos, el conde se quedará encerrado lejos de Londres y de sus amigos.', 'meta': 'Los dos sitios para cruzar el río están marcados con una estrella. Pisa los dos con tus soldados y consigue que sigan siendo tuyos durante tres turnos seguidos. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los galeses del conde y los barones rebeldes. Cada uno va por su cuenta', 'consejo': 'Necesitas los dos a la vez. Deja soldados fuertes encima de cada uno.', 'en': {'nombre': 'The bridges of the Severn', 'voz': 'Roger Mortimer', 'historia': 'You have an army now. Earl Simon is on the other side of the Severn, a very big river, and the Welsh are helping him. There are only two places to cross the river. If we close them, the earl will be trapped far from London and his friends.', 'meta': 'The two crossing places are marked with a star. Step on both of them with your soldiers and keep them yours for three turns in a row. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "The earl's Welsh and the rebel barons. Each fights for himself", 'consejo': 'You need both at the same time. Leave strong soldiers on top of each one.'}}, {'id': 5, 'nombre': 'Gloucester', 'mapa': 'marca', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 12, 'dificultad': 'normal', 'limite': 16, 'guion': [{'id': 'maquinas_gilbert', 'cuando': {'turno': 5}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['catapulta', 'catapulta'], 'donde': 'borde'}, 'aviso': 'catapultas'}}], 'enemigos': [{'bando': 'inglaterra', 'reino': 'Los hombres del conde', 'capital': 'Gloucester'}, {'bando': 'inglaterra', 'reino': 'Los barones rebeldes'}], 'voz': 'Gilbert de Clare, un conde', 'historia': 'Antes estaba con Simón, pero me he cansado de sus órdenes, y ahora estoy contigo, príncipe. Mi ciudad, Gloucester, la tienen todavía los hombres del conde. Tiene buenas murallas: habrá que romperlas.', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista Gloucester, la ciudad que tienen los hombres del conde. Tienes {t} turnos. Si se acaban y no la has conquistado, pierdes.', 'contra': 'Los hombres del conde y los barones rebeldes. Cada uno va por su cuenta', 'consejo': 'Aquí no puedes reclutar soldados, así que cuídalos. Sin catapultas cuesta mucho romper una muralla.', 'avisos': {'catapultas': 'Gilbert te manda dos catapultas desde sus tierras. Sirven para romper murallas.'}, 'en': {'nombre': 'Gloucester', 'voz': 'Gilbert de Clare, an earl', 'historia': "I used to be with Simon, but I'm tired of his orders, and now I'm with you, prince. My city, Gloucester, is still held by his men. It has good walls: we'll have to break them.", 'meta': 'You have no village here: only your army. Conquer Gloucester, the city held by the earl’s men. You have {t} turns. If they run out and you haven’t conquered it, you lose.', 'contra': 'The earl’s men and the rebel barons. Each fights for himself', 'consejo': "You can't recruit soldiers here, so look after them. Without catapults it's very hard to break a wall.", 'avisos': {'catapultas': 'Gilbert sends you two catapults from his lands. They are for breaking walls.'}}}, {'id': 6, 'nombre': 'Kenilworth', 'mapa': 'isla', 'rivales': 2, 'batalla': 'campo', 'ejercito': {'yo': 14, 'rival': 3}, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'heroe'}, 'dificultad': 'dificil', 'limite': 12, 'guion': [{'id': 'despiertan', 'repetible': True, 'cuando': {'cadaTurnos': 3, 'desde': 3}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero', 'espadachin'], 'donde': 'borde'}, 'aviso': 'despiertan'}}], 'enemigos': [{'bando': 'francia', 'reino': 'El joven Simón'}, {'bando': 'francia', 'reino': 'Los caballeros del joven Simón'}], 'voz': 'Gilbert de Clare', 'historia': 'El hijo del conde, que también se llama Simón, viene a ayudar a su padre con otro ejército. Han llegado cansados y duermen fuera del castillo de Kenilworth, junto al lago. Si atacamos de madrugada, antes de que se despierten todos, no llegarán a ayudar a su padre.', 'meta': 'Mata a los héroes de los dos jefes enemigos y que el tuyo siga vivo. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'El joven Simón y sus caballeros, que van juntos', 'consejo': 'Date prisa: cuanto más tardes, más enemigos se despiertan. Cuida a tu héroe: si lo matan, pierdes.', 'avisos': {'despiertan': '¡Se despiertan más caballeros del joven Simón y vienen a pelear!'}, 'en': {'nombre': 'Kenilworth', 'voz': 'Gilbert de Clare', 'historia': "The earl's son, who is also called Simon, is coming to help his father with another army. They arrived tired and are sleeping outside Kenilworth castle, by the lake. If we attack at dawn, before they all wake up, they will never reach his father.", 'meta': 'Kill the heroes of both enemy leaders and keep yours alive. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'Young Simon and his knights, who fight together', 'consejo': 'Hurry: the longer you take, the more enemies wake up. Look after your hero: if yours is killed, you lose.', 'avisos': {'despiertan': "More of young Simon's knights wake up and come to fight!"}}}, {'id': 7, 'nombre': 'Las colinas de Gales', 'mapa': 'sierra', 'rivales': 3, 'equipos': [0, 1, 1, 1], 'objetivo': {'tipo': 'aguantar', 'equipo': 0, 'turnos': 16, 'capital': True}, 'dificultad': 'dificil', 'limite': 16, 'guion': [{'id': 'galeses', 'repetible': True, 'cuando': {'cadaTurnos': 2, 'desde': 4}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['arquero', 'espadachin', 'catapulta', 'caballero'], 'donde': 'borde'}, 'aviso': 'galeses'}}], 'enemigos': [{'bando': 'escocia', 'reino': 'Los galeses de Llywelyn'}, {'bando': 'escocia', 'reino': 'Los arqueros galeses'}, {'bando': 'escocia', 'reino': 'Los galeses de las colinas'}], 'voz': 'Gilbert de Clare', 'historia': 'Llywelyn, el príncipe de Gales, manda a sus arqueros a ayudar al conde. Nacieron en estas colinas y conocen cada camino. Nos han rodeado. Nuestro ejército viene de camino: hay que aguantar hasta que llegue.', 'meta': 'Defiende tu pueblo principal (el de la estrella) durante {t} turnos, hasta que llegue tu ejército. Si te lo quitan, pierdes. Si al acabar el turno {t} sigue siendo tuyo, ganas.', 'contra': 'Tres grupos de galeses de Llywelyn, que van juntos', 'consejo': 'Llena tu pueblo principal de soldados y ponle murallas. Los demás pueblos no importan tanto.', 'avisos': {'galeses': '¡Bajan más galeses de las colinas, con una catapulta para romper tus murallas!'}, 'en': {'nombre': 'The hills of Wales', 'voz': 'Gilbert de Clare', 'historia': 'Llywelyn, the prince of Wales, is sending his archers to help the earl. They were born in these hills and know every path. They have surrounded us. Our army is on its way: we have to hold out until it arrives.', 'meta': "Defend your main village (the one with the star) for {t} turns, until your army arrives. If they take it, you lose. If it's still yours at the end of turn {t}, you win.", 'contra': "Three groups of Llywelyn's Welsh, who fight together", 'consejo': "Fill your main village with soldiers and give it walls. Your other villages don't matter as much.", 'avisos': {'galeses': 'More Welsh come down from the hills, with a catapult to break your walls!'}}}, {'id': 8, 'nombre': 'Los arqueros del rey', 'mapa': 'costa', 'rivales': 3, 'batalla': 'campo', 'ejercito': {'yo': 15, 'rival': 4}, 'equipos': [0, 1, 1, 1], 'dificultad': 'dificil', 'limite': 15, 'enemigos': [{'bando': 'francia', 'reino': 'Los caballeros del conde'}, {'bando': 'inglaterra', 'reino': 'Los barones rebeldes'}, {'bando': 'inglaterra', 'reino': 'Los barones del sur'}], 'voz': 'Gilbert de Clare', 'historia': 'Has aprendido algo de los galeses, príncipe: sus arcos largos llegan más lejos que cualquier cosa. Ahora tú también tienes arqueros así. El conde manda a sus caballeros contra nosotros en campo abierto. Pon a los arqueros detrás de las lanzas.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los caballeros del conde y dos grupos de barones, que van juntos', 'consejo': 'Pon lanceros delante y arqueros detrás: los caballos no quieren chocar contra las lanzas.', 'en': {'nombre': "The king's archers", 'voz': 'Gilbert de Clare', 'historia': "You've learnt something from the Welsh, prince: their longbows reach further than anything. Now you have archers like that too. The earl is sending his knights against us in open field. Put the archers behind the spears.", 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "The earl's knights and two groups of barons, who fight together", 'consejo': "Put spearmen in front and archers behind: horses don't like charging into spears."}}, {'id': 9, 'nombre': 'El paso del Avon', 'mapa': 'marca', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'tomar', 'jugador': 1}, 'dificultad': 'normal', 'limite': 30, 'enemigos': [{'bando': 'inglaterra', 'reino': 'Los barones del paso'}, {'bando': 'inglaterra', 'reino': 'Los barones rebeldes'}], 'voz': 'Roger Mortimer', 'historia': 'El conde Simón escapa hacia el sur para juntarse con su hijo. No sabe que su hijo ya no tiene ejército. Solo le queda un camino, y pasa por el pueblo que guarda el paso del río Avon. Si lo tomamos antes que él, lo tendremos atrapado.', 'meta': 'Conquista el pueblo de los barones del paso, que es su pueblo principal. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los barones del paso y los barones rebeldes, que van juntos', 'consejo': 'No hace falta acabar con todos: solo con ese pueblo. Lleva catapultas si tiene muralla.', 'en': {'nombre': 'The Avon crossing', 'voz': 'Roger Mortimer', 'historia': "Earl Simon is escaping south to join his son. He doesn't know his son has no army left. He has only one road, and it goes through the village that guards the crossing of the river Avon. If we take it before he gets there, he'll be trapped.", 'meta': "Conquer the village of the barons of the crossing, which is their main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The barons of the crossing and the rebel barons, who fight together', 'consejo': "You don't have to beat everyone: just that village. Bring catapults if it has a wall.", 'avisos': {'mortimer': 'Mortimer sends you soldiers and three catapults. They arrive near the crossing, ready to break its wall.', 'mortimer2': 'Mortimer sends more help near the crossing: two knights and another catapult.'}}, 'guion': [{'id': 'mortimer_paso', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['lancero', 'arquero', 'catapulta', 'catapulta', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'mortimer'}}, {'id': 'mortimer2', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'caballero', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'mortimer2'}}], 'avisos': {'mortimer': 'Mortimer te manda soldados y tres catapultas. Llegan cerca del paso, listos para romper su muralla.', 'mortimer2': 'Mortimer manda más ayuda cerca del paso: dos caballeros y otra catapulta.'}, 'hucha': None}, {'id': 10, 'nombre': 'Evesham', 'mapa': 'marca', 'rivales': 2, 'equipos': [0, 1, 1], 'dificultad': 'dificil', 'limite': 30, 'guion': [{'id': 'mortimer', 'cuando': {'turno': 7}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'caballero', 'arquero_largo'], 'donde': 'borde'}, 'aviso': 'mortimer'}}, {'id': 'maquinas_gilbert', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'catapulta', 'catapulta'], 'donde': 'borde'}, 'aviso': 'maquinas'}}], 'enemigos': [{'bando': 'francia', 'capital': 'Evesham'}, {'bando': 'inglaterra', 'reino': 'Los barones rebeldes'}], 'voz': 'Simón de Montfort, el conde', 'historia': '«Príncipe Eduardo. Cuando eras un niño, yo mismo te enseñé a manejar la espada. Veo que aprendiste bien… pero no tanto como para ganarme.» El conde Simón te mira desde la villa de Evesham, con el río detrás. «Aquí, entre el agua y la colina, se decide quién manda en Inglaterra.»', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista Evesham, el pueblo principal del conde Simón. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'El conde Simón y los barones rebeldes, que van juntos', 'consejo': 'Es la última batalla. El conde es muy fuerte: no le ataques con un soldado solo.', 'avisos': {'mortimer': 'Llega Roger Mortimer con sus hombres para ayudarte: dos caballeros y un arquero de arco largo.', 'maquinas': 'Gilbert llega con un caballero y dos catapultas para romper la muralla de Evesham.'}, 'en': {'nombre': 'Evesham', 'voz': 'Simon de Montfort, the earl', 'historia': "«Prince Edward. When you were a boy, I taught you to use a sword myself. I see you learnt well… but not well enough to beat me.» Earl Simon looks at you from the town of Evesham, with the river behind him. «Here, between the water and the hill, we'll decide who rules England.»", 'meta': "You have no village here: only your army. Conquer Evesham, Earl Simon's main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'Earl Simon and the rebel barons, who fight together', 'consejo': "This is the last battle. The earl is very strong: don't attack him with just one soldier.", 'avisos': {'mortimer': 'Roger Mortimer arrives with his men to help you: two knights and a longbowman.', 'maquinas': 'Gilbert arrives with a knight and two catapults to break the wall of Evesham.'}}, 'batalla': 'asalto', 'ejercito': 18}]
REINOS_EN = {'Los hombres del conde': "The earl's men", 'Los hombres de Knut': "Knut's men", 'Los piratas del estrecho': 'The pirates of the strait', 'Los señores de la isla': 'The lords of the island', 'Los señores del puerto': 'The lords of the harbour', 'Los soldados del emperador': "The emperor's soldiers", 'La guardia del palacio': 'The palace guard', 'Los bandidos del río': 'The river bandits', 'Los bandidos del bosque': 'The forest bandits', 'Los jefes del fiordo': 'The chiefs of the fjord', 'Magnus, tu sobrino': 'Magnus, your nephew', 'Los barcos de Svein': "Svein's ships", 'Los señores de las islas': 'The lords of the isles', 'Los señores del cabo': 'The lords of the cape', 'El conde de las Orcadas': 'The earl of Orkney', 'El conde Edwin': 'Earl Edwin', 'El conde Morcar': 'Earl Morcar', 'Los sajones': 'The Saxons', 'Los sajones del río': 'The river Saxons', 'Los guardias del conde': "The earl's guards", 'Los jinetes del conde': "The earl's riders", 'Los barones del valle': 'The barons of the valley', 'Los barones del río': 'The barons of the river', 'Los galeses del conde': "The earl's Welsh", 'Los barones rebeldes': 'The rebel barons', 'La guarnición de Gloucester': 'The garrison of Gloucester', 'El joven Simón': 'Young Simon', 'Los caballeros del joven Simón': "Young Simon's knights", 'Los galeses de Llywelyn': "Llywelyn's Welsh", 'Los caballeros del conde': "The earl's knights", 'Los barones del sur': 'The barons of the south', 'Los barones del paso': 'The barons of the crossing', 'Los barones del conde': "The earl's barons", 'Los bandidos del vado': 'The bandits of the ford', 'Los barones del monte': 'The barons of the hill'}
